struct Point<T> {
    x: T,
    y: T,
}

impl<T> Point<T> {
    fn x(&self) -> &T {
        &self.x
    }
}

fn main() {
    let whole = Point { x: 5, y: 10 };
    let fractional = Point { x: 1.5, y: 4.0 };
    println!("{} {}", whole.x(), whole.y);
    println!("{} {}", fractional.x(), fractional.y);
}

struct Point<T> {
    x: T,
    y: T,
}

impl Point<f64> {
    fn distance_from_origin(&self) -> f64 {
        (self.x * self.x + self.y * self.y).sqrt()
    }
}

fn main() {
    let p = Point { x: 3.0, y: 4.0 };
    println!("distance: {}", p.distance_from_origin());
}

// Copies of the standard library definitions (simplified), shown for reading
enum Option<T> {
    Some(T),
    None,
}

enum Result<T, E> {
    Ok(T),
    Err(E),
}

struct Stack<T> {
    items: Vec<T>,
}

impl<T> Stack<T> {
    fn new() -> Stack<T> {
        Stack { items: Vec::new() }
    }

    fn push(&mut self, item: T) {
        self.items.push(item);
    }

    fn pop(&mut self) -> Option<T> {
        self.items.pop()
    }

    fn peek(&self) -> Option<&T> {
        self.items.last()
    }
}

fn main() {
    let mut plates: Stack<String> = Stack::new();
    plates.push(String::from("blue"));
    plates.push(String::from("red"));
    println!("top: {:?}", plates.peek());
    println!("took: {:?}", plates.pop());
    println!("took: {:?}", plates.pop());
    println!("took: {:?}", plates.pop());
}

