struct Pair {
    left: i32,
    right: i32,
}

impl Pair {
    fn swapped(self) -> Pair {
        Pair { left: self.right, right: self.left }
    }
}

fn main() {
    let numbers = Pair { left: 1, right: 2 }.swapped();
    println!("{} {}", numbers.left, numbers.right);
    let words = Pair { left: "a", right: "b" }.swapped();
    println!("{} {}", words.left, words.right);
}

